    drawPlayerSprite(b.cap.state==='hostile'?sprCap:sprCap,b.cap.x,b.cap.y);
  // player
  if(player.active&&G.state!=='over'&&G.state!=='stats'){
    const blink=player.invuln>0&&((G.tick>>2)&1);
    if(!blink){
