  if(captureAnim)drawPlayerSprite(sprCap,captureAnim.x,captureAnim.y);
  for(const b of booms)drawBoom(b);
  drawHUD();
  if(G.state==='intro'){
    text(isChal(G.stage)?'CHALLENGING STAGE':'STAGE '+G.stage,112,150,isChal(G.stage)?'#ff4040':'#ffffff',10,'center');
  }
  if((G.state==='play'||G.state==='chal')&&G.readyTimer>0)
    text('READY',112,180,'#ffff40',10,'center');
  if(G.state==='chal'){
    text('WAVE '+G.chalWave+'/5',112,40,'#40a0ff',8,'center');
    text('HITS '+G.totalHits,112,50,'#ffffff',8,'center');
  }
  if(G.state==='chalEnd'){
    text('NUMBER OF HITS',112,110,'#40a0ff',10,'center');
    text(String(G.totalHits),112,128,'#ffffff',10,'center');
    if(G.waveBonuses)text('BONUS '+G.waveBonuses+'000 PTS',112,148,'#ffe080',9,'center');
    if(G.totalHits>=40)text('PERFECT!  10000 PTS',112,166,'#ff4040',10,'center');
  }
  if(G.state==='over')text('GAME OVER',112,150,'#ff4040',12,'center');
  if(G.state==='stats'){
    text('NUMBER OF SHOTS',112,100,'#40a0ff',9,'center');
    text(String(G.shotsFired),112,116,'#ffffff',9,'center');
    text('NUMBER OF HITS',112,140,'#40a0ff',9,'center');
    text(String(G.hits),112,156,'#ffffff',9,'center');
    const r=G.shotsFired?Math.round(G.hits/G.shotsFired*100):0;
    text('HIT-MISS RATIO',112,180,'#40a0ff',9,'center');
    text(r+' %',112,196,'#ffffff',9,'center');
  }
  if(G.paused)text('PAUSED',112,144,'#ffff40',10,'center');
  if(muted)text('MUTE',8,H-24,'#808080',7);
}

/* ---------- Fixed-timestep main loop ---------- */
let last=performance.now(),acc=0;const DT=1/60;
function frame(now){
  requestAnimationFrame(frame);
  acc+=Math.min((now-last)/1000,0.1);last=now;
  while(acc>=DT){update(DT);acc-=DT;}
  render(now);
}
requestAnimationFrame(frame);
